import { ChangeDetectionStrategy, Component, computed, inject, signal, OnInit } from '@angular/core';
import { MPageService, ReferenceService } from '@clinicaloffice/mpage-developer';
import { ServiceRegistryService } from '../../services/service-registry.service';
import { CclExecutorService } from '../../services/ccl-executor.service';
import { ClinicalOfficeExecutorService } from '../../services/clinical-office-executor.service';
import { ServiceDefinition, ExecutionResult } from '../../models/service-definition.model';
import { ParameterForm } from '../../components/parameter-inputs/parameter-form';
import { JsonViewer } from '../../components/json-viewer/json-viewer';
import { HelpModal } from '../../components/help-modal/help-modal';

@Component({
  selector: 'app-executor',
  standalone: true,
  imports: [ParameterForm, JsonViewer, HelpModal],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './executor.html',
  styleUrl: './executor.scss'
})
export class Executor implements OnInit {
  private registry = inject(ServiceRegistryService);
  private rawExecutor = inject(CclExecutorService);
  private coExecutor = inject(ClinicalOfficeExecutorService);
  private referenceService = inject(ReferenceService);

  public MPage = inject(MPageService);

  /** All available services */
  readonly services = this.registry.allServices;

  /** Currently selected service ID */
  readonly selectedServiceId = signal<string>('cov_doc_activity_extract');

  /** Resolved selected service */
  readonly selectedService = computed(() =>
    this.registry.getService(this.selectedServiceId())
  );

  /** Execution mode: raw XMLCclRequest or Clinical Office CustomService */
  readonly executionMode = signal<'raw' | 'clinical-office'>('raw');

  /** Whether to include reference data in Clinical Office mode */
  readonly includeReference = signal(false);

  /** Whether reference data has been loaded */
  readonly referenceLoaded = signal(false);

  /**
   * Whether the Clinical Office initialization check has timed out.
   * After 5 seconds, if serviceReady is still false, we assume standalone mode.
   */
  readonly standaloneMode = signal(false);

  /** Tooltip text for the Clinical Office button when disabled */
  readonly coButtonTooltip = computed(() => {
    if (this.MPage.serviceReady) return 'Execute via Clinical Office CustomService';
    if (this.standaloneMode()) return 'Standalone mode \u2014 Clinical Office unavailable';
    return 'Waiting for Clinical Office...';
  });

  /** Whether a script is currently executing */
  readonly executing = computed(() =>
    this.executionMode() === 'raw'
      ? this.rawExecutor.executing()
      : this.coExecutor.executing()
  );

  /** Current execution result */
  readonly currentResult = signal<ExecutionResult | null>(null);

  /** Execution history (merged from both engines) */
  readonly history = computed(() => {
    const raw = this.rawExecutor.history();
    const co = this.coExecutor.history();
    return [...raw, ...co]
      .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
      .slice(0, 50);
  });

  /** Whether the history drawer is open */
  readonly historyOpen = signal(false);

  /** Whether the help modal is open */
  readonly helpOpen = signal(false);

  /** Whether the params string is expanded */
  readonly paramsExpanded = signal(false);

  /** Whether params were just copied */
  readonly paramsCopied = signal(false);

  ngOnInit(): void {
    // Poll for Clinical Office readiness with 5-second timeout
    // Matches cernertools CernerDetectionService pattern
    if (!this.MPage.serviceReady) {
      const startTime = Date.now();
      const interval = setInterval(() => {
        if (this.MPage.serviceReady) {
          clearInterval(interval);
        } else if (Date.now() - startTime > 5000) {
          clearInterval(interval);
          this.standaloneMode.set(true);
        }
      }, 500);
    }
  }

  /** Select a service */
  selectService(id: string): void {
    this.selectedServiceId.set(id);
    this.currentResult.set(null);
  }

  /** Set execution mode */
  setMode(mode: 'raw' | 'clinical-office'): void {
    this.executionMode.set(mode);
    if (mode === 'raw') {
      this.includeReference.set(false);
    }
  }

  /** Execute the selected service with given parameter values */
  async onExecute(parameterValues: Record<string, string>): Promise<void> {
    const service = this.selectedService();
    if (!service) return;

    let result: ExecutionResult;

    if (this.executionMode() === 'clinical-office') {
      result = await this.coExecutor.execute(service, parameterValues, {
        reference: this.includeReference()
      });
    } else {
      result = await this.rawExecutor.execute(service, parameterValues);
    }

    this.currentResult.set(result);
  }

  /** Load Reference Service data and log to MPage log */
  loadReference(): void {
    this.referenceService.loadCoreReference();
    this.referenceLoaded.set(true);

    const keys = this.referenceService.references();
    this.MPage.putLog(`Reference Service loaded. Keys: [${keys.join(', ')}]`);

    for (const key of keys) {
      const ref = this.referenceService.get(key);
      this.MPage.putLog(`Reference: ${key}\n${JSON.stringify(ref, null, 2)}`);
    }

    this.MPage.putLog(`Reference loading complete. Total keys: ${keys.length}`);
  }

  /** Load a result from history */
  loadFromHistory(result: ExecutionResult): void {
    this.currentResult.set(result);
  }

  /** Clear the current result */
  clearResult(): void {
    this.currentResult.set(null);
  }

  /** Toggle the history drawer */
  toggleHistory(): void {
    this.historyOpen.update(v => !v);
  }

  /** Clear all history */
  clearHistory(): void {
    this.rawExecutor.clearHistory();
    this.coExecutor.clearHistory();
    this.historyOpen.set(false);
  }

  /** Copy parameter string to clipboard */
  copyParams(params: string): void {
    navigator.clipboard.writeText(params);
    this.paramsCopied.set(true);
    setTimeout(() => this.paramsCopied.set(false), 2000);
  }

  /** Format a timestamp for display */
  formatTime(date: Date): string {
    return new Date(date).toLocaleTimeString();
  }

  /** Format duration for display */
  formatDuration(ms: number): string {
    if (ms < 1000) return `${ms}ms`;
    return `${(ms / 1000).toFixed(1)}s`;
  }
}
